// Action function for rule: LitMatcher
fn onLitMatcher(c: *interpreter.Current, lit: interpreter.Value, ignore: interpreter.Value) !interpreter.Value {
    
    const raw_str = lit.value;
    const unquoted = try std.mem.replaceOwned(u8, c.allocator, raw_str, "\"", "");
    const lit_matcher = try c.allocator.create(ast.LitMatcher);
    lit_matcher.* = ast.LitMatcher{
        .pos = c.astPos(),
        .value = unquoted,
        .ignore_case = ignore != null,
    };
    return ast.Expression{ .lit_matcher = lit_matcher };

}

// Action function for rule: StringLiteral
fn onStringLiteral(c: *interpreter.Current) !interpreter.Value {
    
    return ast.StringLit{
        .pos = c.astPos(),
        .value = try c.allocator.dupe(u8, c.text),
    };

}

